connect.lines:
with process: stripe STRIPE_API_POST /v1/refunds | body=={amount: amount, currency: currency} | result=stripeRefund: response.body
with update: stripe STRIPE_API_GET /v1/refunds/{{stripeRefund.id}} | result=refundStatus: response.body
with decline: http POST https://api.example.com/notifications | token={{secrets.NOTIFICATION_TOKEN}} | body=={to: email, message: "Refund declined"}

connect.raw:
