with update: stripe STRIPE_API_GET /v1/refunds/{{stripeRefund.id}} | result=refundStatus: response.body
with decline: http POST https://api.example.com/notifications | token={{secrets.NOTIFICATION_TOKEN}} | body=={to: email, message: "Refund declined"}

connect.lines:
with sheet: google-sheets addValues | authentication.authType=refresh | oauthClientId={{secrets.GOOGLE_CLIENT_ID}} | oauthClientSecret={{secrets.GOOGLE_CLIENT_SECRET}} | oauthRefreshToken={{secrets.GOOGLE_CLIENT_REFRESH_TOKEN}} | addValues.spreadsheetId={{secrets.SPREADSHEET_ID}} | addValues.worksheetName=Leads | cellId=A1 | value==concatenate([[leadName], [leadEmail], [leadPhone]])
with notify: http POST https://outlook.office.com/webhook/{webhookUrl}/incomingWebhook | data=={"text": "New Lead: " + leadName + " - " + leadPhone}
with done: end Process Complete

