connect.lines:
with webhook-start: webhook-start Webhook Start Event Connector | inbound.context=inbound.context
with check: http Send REST Request | url=http://inventory-service/api/stock | resultVariable=stock
with teamsChat: teams createChat Microsoft Teams Outbound Connector | clientId={{secrets.CLIENT_ID}} | tenantId={{secrets.TENANT_ID}} | clientSecret={{secrets.CLIENT_SECRET}} | data.createChat.members=warehouse-emails@example.com | data.createChat.chatType=group | resultVariable=chatId
with notify: teams sendMessageToChat Microsoft Teams Outbound Connector | chatId={{chatId}} | content== "New order requires restocking. Please review." | clientId={{secrets.CLIENT_ID}} | tenantId={{secrets.TENANT_ID}} | clientSecret={{secrets.CLIENT_SECRET}}
with restock: http Send REST Request | url=http://inventory-service/api/restock | method=POST | body=={action: "restock"}

